export function getServiceClaimDishwasherMask(kitchenSlug) {
  return MASKS_BY_LAYOUT[LAYOUT_BY_SLUG[String(kitchenSlug || "").trim().toLowerCase()]] || null;
}
export const SERVICE_CLAIM_DISHWASHER_MASK_SLUGS = Object.keys(LAYOUT_BY_SLUG);

/** Shared ASC/email overlay for older CAD drawings without appliance symbols. */
export function buildServiceClaimDishwasherSvgOverlay({ kitchenSlug, selectedComponentIds = [] }) {
  const mask = getServiceClaimDishwasherMask(kitchenSlug);
  if (!mask?.svgOverlay) return '';
  const selected = new Set(selectedComponentIds);
  const paint = (id) => selected.has(id) ? 'rgba(62,188,116,0.34)' : 'transparent';
  const polygon = (points) => points.map(([x,y]) => [x*8,y*6].join(',')).join(' ');
  const b=mask.sourceBounds;
  const front=[[b.left,b.top],[b.left+b.width,b.top],[b.left+b.width,b.top+b.height],[b.left,b.top+b.height]];
  const rimY=(b.top+.43*b.height)*6, floorY=(b.top+.67*b.height)*6;
  const wires=Array.from({length:8},(_,i)=>{const u=i/7;return '<line x1="'+(b.left+(.12+.76*u)*b.width)*8+'" y1="'+rimY+'" x2="'+(b.left+(.18+.64*u)*b.width)*8+'" y2="'+floorY+'"/>';}).join('');
  const gs=mask.gsPoints;
  return '<g data-claim-dishwasher-overlay="true"><g data-component-id="component-claim-furniture-front"><polygon points="'+polygon(front)+'" fill="'+paint('component-claim-furniture-front')+'" stroke="none" pointer-events="all"/></g><g data-component-id="component-claim-dishwasher"><polygon points="'+polygon(mask.basketPoints)+'" fill="'+paint('component-claim-dishwasher')+'" stroke="#d5d5d5" pointer-events="all"/><g stroke="#d5d5d5" stroke-width="0.5" pointer-events="none">'+wires+'</g><polygon points="'+polygon(gs)+'" fill="'+paint('component-claim-dishwasher')+'" stroke="#777" pointer-events="all"/><text x="'+(gs[0][0]+gs[1][0])*4+'" y="'+((gs[0][1]+gs[2][1])*3+4)+'" font-size="12" text-anchor="middle" fill="#777" pointer-events="none">GS</text></g></g>';
}
